INSERT INTO "Question" ("id","prompt","options","correctIndex","explanation","difficulty","answers","hint","order","courseId","levelId","createdAt") VALUES
('q_aj-p-casy_0','Doplň: She … to school every day.',ARRAY['go','gone','goes','going']::TEXT[],2,'Zvykové děje v přítomném čase prostém; ve 3. osobě přidáváme -s: goes.',1,ARRAY[]::TEXT[],NULL,0,'c_aj-p-casy',NULL,NOW()),
('q_aj-p-casy_1','Doplň: Look! I … a book now.',ARRAY['am reading','reads','am read','read']::TEXT[],0,'Děj probíhající právě teď = přítomný čas průběhový: am reading.',1,ARRAY[]::TEXT[],NULL,1,'c_aj-p-casy',NULL,NOW()),
('q_aj-p-casy_2','Doplň: Yesterday we … football.',ARRAY['played','plays','playing','play']::TEXT[],0,'Yesterday = minulý čas: played.',1,ARRAY[]::TEXT[],NULL,2,'c_aj-p-casy',NULL,NOW()),
('q_aj-p-casy_3','Doplň: He … TV at the moment.',ARRAY['watched','is watching','watch','watches']::TEXT[],1,'At the moment = přítomný čas průběhový.',2,ARRAY[]::TEXT[],NULL,3,'c_aj-p-casy',NULL,NOW()),
('q_aj-p-casy_4','Doplň: I … my homework yet.',ARRAY['am not finishing','wasn''t finish','haven''t finished','don''t finish']::TEXT[],2,'Yet se záporem = present perfect: haven''t finished.',2,ARRAY[]::TEXT[],NULL,4,'c_aj-p-casy',NULL,NOW()),
('q_aj-p-casy_5','Doplň: We … to Prague tomorrow.',ARRAY['went','will go','were going','have been']::TEXT[],1,'Tomorrow = budoucnost: will go.',2,ARRAY[]::TEXT[],NULL,5,'c_aj-p-casy',NULL,NOW()),
('q_aj-p-casy_6','Jak se správně řekne: „Prší už dvě hodiny“?',ARRAY['It rains since two hours.','It rained for two hours now.','It is raining for two hours.','It has been raining for two hours.']::TEXT[],3,'Děj trvající do současnosti = present perfect continuous + for.',3,ARRAY[]::TEXT[],NULL,6,'c_aj-p-casy',NULL,NOW()),
('q_aj-p-casy_7','Doplň: While I … TV, the phone rang.',ARRAY['will watch','was watching','watches','am watching']::TEXT[],1,'Probíhající děj v minulosti přerušený jiným dějem = minulý průběhový čas.',3,ARRAY[]::TEXT[],NULL,7,'c_aj-p-casy',NULL,NOW()),
('q_aj-p-casy_8','Doplň: If it rains tomorrow, we … at home.',ARRAY['had stayed','would stay','will stay','stayed']::TEXT[],2,'První kondicionál: If + přítomný čas, will + infinitiv.',3,ARRAY[]::TEXT[],NULL,8,'c_aj-p-casy',NULL,NOW()),
('q_aj-p-casy_9','Doplň: I have lived here … 2010.',ARRAY['during','since','for','ago']::TEXT[],1,'Since říká, odkdy děj trvá (bod v čase); for říká, jak dlouho.',4,ARRAY[]::TEXT[],NULL,9,'c_aj-p-casy',NULL,NOW()),
('q_aj-p-casy_10','Která věta je správná?',ARRAY['How long you are learning English?','How long have you been learning English?','How long do you learn English since?','How long did you have learned English?']::TEXT[],1,'Otázka na délku trvání: How long have you been …ing?',4,ARRAY[]::TEXT[],NULL,10,'c_aj-p-casy',NULL,NOW()),
('q_aj-p-casy_11','Která věta je správná?',ARRAY['I am seen that film twice.','I has seen that film twice.','I have saw that film twice.','I have seen that film twice.']::TEXT[],3,'Present perfect: have/has + 3. tvar slovesa (seen).',4,ARRAY[]::TEXT[],NULL,11,'c_aj-p-casy',NULL,NOW()),
('q_aj-p-casy_12','Vyber správný trpný rod: „Charles IV founded the university.“',ARRAY['The university was founded by Charles IV.','The university founded by Charles IV.','The university was found by Charles IV.','The university were founded by Charles IV.']::TEXT[],0,'Trpný rod: was/were + 3. tvar (founded).',5,ARRAY[]::TEXT[],NULL,12,'c_aj-p-casy',NULL,NOW()),
('q_aj-p-casy_13','Doplň: By the time we got there, the film …',ARRAY['has already started','had already started','is already starting','already start']::TEXT[],1,'Děj před jiným dějem v minulosti = past perfect.',5,ARRAY[]::TEXT[],NULL,13,'c_aj-p-casy',NULL,NOW()),
('q_aj-p-casy_14','Doplň: I wish I … more time.',ARRAY['have','had','will have','has']::TEXT[],1,'Přání týkající se přítomnosti se vyjadřuje minulým časem: I wish I had.',5,ARRAY[]::TEXT[],NULL,14,'c_aj-p-casy',NULL,NOW()),
('q_aj-p-clenky-predlozky_0','Doplň: I have … apple.',ARRAY['two','many','an','a']::TEXT[],2,'Před slovem začínajícím samohláskovým zvukem použijeme an.',1,ARRAY[]::TEXT[],NULL,0,'c_aj-p-clenky-predlozky',NULL,NOW()),
('q_aj-p-clenky-predlozky_1','Doplň: The book is … the table.',ARRAY['at','to','on','in']::TEXT[],2,'On the table = na stole.',1,ARRAY[]::TEXT[],NULL,1,'c_aj-p-clenky-predlozky',NULL,NOW()),
('q_aj-p-clenky-predlozky_2','Doplň: She lives … London.',ARRAY['in','at','to','on']::TEXT[],0,'Ve městech používáme in.',1,ARRAY[]::TEXT[],NULL,2,'c_aj-p-clenky-predlozky',NULL,NOW()),
('q_aj-p-clenky-predlozky_3','Doplň: My birthday is … May.',ARRAY['at','on','to','in']::TEXT[],3,'S měsíci používáme in.',2,ARRAY[]::TEXT[],NULL,3,'c_aj-p-clenky-predlozky',NULL,NOW()),
('q_aj-p-clenky-predlozky_4','Doplň: We have lunch … 12 o''clock.',ARRAY['in','at','on','by']::TEXT[],1,'S přesným časem používáme at.',2,ARRAY[]::TEXT[],NULL,4,'c_aj-p-clenky-predlozky',NULL,NOW()),
('q_aj-p-clenky-predlozky_5','Doplň: I was born … 5th March.',ARRAY['since','at','on','in']::TEXT[],2,'S konkrétním datem a dny používáme on.',2,ARRAY[]::TEXT[],NULL,5,'c_aj-p-clenky-predlozky',NULL,NOW()),
('q_aj-p-clenky-predlozky_6','Doplň: … sun rises in the east.',ARRAY['An','The','A','Some']::TEXT[],1,'Jedinečné věci (slunce) mají určitý člen the.',3,ARRAY[]::TEXT[],NULL,6,'c_aj-p-clenky-predlozky',NULL,NOW()),
('q_aj-p-clenky-predlozky_7','Doplň: She plays … piano very well.',ARRAY['some','an','a','the']::TEXT[],3,'S hudebními nástroji používáme the.',3,ARRAY[]::TEXT[],NULL,7,'c_aj-p-clenky-predlozky',NULL,NOW()),
('q_aj-p-clenky-predlozky_8','Doplň: He is … university student.',ARRAY['any','two','an','a']::TEXT[],3,'University začíná zvukem /j/, proto a.',3,ARRAY[]::TEXT[],NULL,8,'c_aj-p-clenky-predlozky',NULL,NOW()),
('q_aj-p-clenky-predlozky_9','Doplň: I''m afraid … spiders.',ARRAY['from','with','at','of']::TEXT[],3,'Afraid of = bát se čeho.',4,ARRAY[]::TEXT[],NULL,9,'c_aj-p-clenky-predlozky',NULL,NOW()),
('q_aj-p-clenky-predlozky_10','Doplň: She is good … maths.',ARRAY['on','at','for','in']::TEXT[],1,'Good at = dobrý v něčem.',4,ARRAY[]::TEXT[],NULL,10,'c_aj-p-clenky-predlozky',NULL,NOW()),
('q_aj-p-clenky-predlozky_11','Doplň: We arrived … the airport at noon.',ARRAY['to','at','in','on']::TEXT[],1,'Arrive at s místem (letiště, nádraží); arrive in s městem.',4,ARRAY[]::TEXT[],NULL,11,'c_aj-p-clenky-predlozky',NULL,NOW()),
('q_aj-p-clenky-predlozky_12','Doplň: He arrived … Prague yesterday.',ARRAY['at','in','on','to']::TEXT[],1,'Arrive in s městem a zemí; arrive to je chyba.',5,ARRAY[]::TEXT[],NULL,12,'c_aj-p-clenky-predlozky',NULL,NOW()),
('q_aj-p-clenky-predlozky_13','Doplň: I''m interested … history.',ARRAY['on','in','at','about']::TEXT[],1,'Interested in = mít zájem o.',5,ARRAY[]::TEXT[],NULL,13,'c_aj-p-clenky-predlozky',NULL,NOW()),
